(() => {
  const A=window.DEMO,U=window.DemoUI,$=s=>document.querySelector(s);
  const desired=Number(new URLSearchParams(location.search).get('week'));if(desired>=1&&desired<=16){week=desired;$('#report-week').value=String(week);}
  render=()=>{
    const rows=A.weekTasks(week),next=A.weekTasks(week+1),s=A.read(),from=Date.UTC(2026,0,5)+(week-1)*7*86400000,to=from+6*86400000,esc=A.esc;
    const sub=id=>A.latest(id),title=t=>'<strong>'+esc(t.name)+' · ID '+t.id+'</strong>',status=id=>A.labels[s.reviews[id]?.state]||'증빙 대기';
    let body='<div class="report-kicker"><span>SAMPLE PROJECT · SITE A</span><span class="tag neutral">시연 보고서</span></div><h2>제'+week+'주 주간 공사 보고서</h2><div class="report-period">2026.'+fmt(from)+' - '+fmt(to)+'</div><p class="report-intro">이번 주 간트 '+rows.length+'개 작업의 일정·사진 증빙·본사 검토 결과를 정리합니다.</p>';
    if(rows.some(t=>t.id==='45'))body+='<section class="report-section"><h3>01 AI 관측 분석</h3><div class="evidence-strip"><img src="'+window.DEMO_DATA.photos.wallAfter+'" alt="벽체 보드 원본 사진"><div class="evidence-copy"><strong>벽체 보드 설치 · ID 45</strong>왼쪽 벽 W01 78.50% · 오른쪽 벽 W02 82.00%<br>설치 ÷ (설치 + 미설치), 인식 불가 제외<br><span class="tag '+A.tone(s.reviews['45'].state)+'">'+esc(status('45'))+'</span><br>관측 수락과 작업 완료 확인을 구분합니다.</div></div></section>';
    const field=rows.filter(t=>sub(t.id));
    body+='<section class="report-section" id="field-results"><h3>02 현장 제출·본사 검토</h3><div class="report-grid">'+(field.map(t=>'<div class="report-mini"><b>'+esc(t.name)+' · ID '+t.id+'</b>'+esc(sub(t.id).report)+'<br><span class="tag '+A.tone(s.reviews[t.id]?.state)+'">'+esc(status(t.id))+'</span></div>').join('')||'<p class="snapshot-note">이 주차에 연결된 제출 사진이 없습니다.</p>')+'</div></section>';
    const extensions=Object.entries(s.extensions).filter(([id])=>rows.some(t=>t.id===id));
    body+='<section class="report-section" id="delay-results"><h3>03 지연·추가 기간 요청</h3>'+(extensions.map(([id,e])=>'<div class="evidence-copy">'+title(A.effectiveTasks().find(t=>t.id===id))+'기존 '+e.original.slice(5).replace('-','.')+' → 요청 '+e.end.slice(5).replace('-','.')+'<br>'+esc(e.reason)+'<br><span class="tag amber">'+({pending:'본사 검토 대기',approved:'수락 · 지연·이월',rejected:'반려'}[e.state])+'</span>'+(e.reviewReason?'<br>반려 사유: '+esc(e.reviewReason):'')+'</div>').join('<br>')||'<p class="snapshot-note">추가 기간 요청 없음</p>')+'</section>';
    body+='<section class="report-section" id="next-work"><h3>04 다음 주 할 일</h3><ul class="next-list">'+next.slice(0,6).map(t=>'<li>'+esc(t.name)+(s.extensions[t.id]?.state==='approved'?' · 지연·이월':'')+'</li>').join('')+'</ul><div class="next-total">전체 '+next.length+'건 · Word 보고서에 모두 포함</div></section>';
    body+='<section class="report-section all-weekly"><h3>05 이번 주 전체 간트 항목</h3><table><thead><tr><th>ID</th><th>작업</th><th>일정</th><th>검토 상태</th></tr></thead><tbody>'+rows.map(t=>'<tr><td>'+t.id+'</td><td>'+esc(t.name)+(Date.parse(t.actualStart||t.start)<from?'<br><small class="muted">지난주부터 진행 · 지난주 내용 포함</small>':'<br><small class="muted">이번 주 시작 · 지난주 내용 생략</small>')+'</td><td>'+t.start.slice(5).replace('-','.')+' - '+t.finish.slice(5).replace('-','.')+'</td><td class="status">'+esc(status(t.id))+'</td></tr>').join('')+'</tbody></table></section><p class="snapshot-note">사진과 검토 결과는 이 브라우저에 저장한 시연 자료입니다. 실제 AI 처리·현장 알림과 연결하지 않았습니다.</p>';
    body+='<section class="report-site-link"><img src="assets/site-qr.png" alt="DEMO 배포 사이트 QR"><div><strong>사진과 검토 이력을 웹에서 확인하세요</strong><p>QR을 스캔하면 DEMO 시연 사이트로 연결됩니다.</p><a href="https://example.com/" target="_blank" rel="noopener">시연 사이트 열기 ↗</a><small>링크가 있으면 누구나 시연 화면을 볼 수 있습니다.</small></div></section>';$('#report-body').innerHTML=body;$('#report-state').textContent='현재 시연 검토 결과 반영';U.badges();
  };
  $('#create-report').onclick=()=>downloadWeeklyReport(week);render();
})();
